/* Cursor state. Both are written and read only from the sampler thread
 * (main.c calls frame_build() -> replay_next()), so no lock is needed.
 * If a second thread ever calls replay_next(), these must become atomic. */
static uint32_t cursor;
static uint32_t passes;

const struct replay_sample *replay_next(void)
{
	const struct replay_sample *s = &replay_samples[cursor];

	if (cursor + 1u < REPLAY_SAMPLE_COUNT) {
		cursor++;
	} else {
#ifdef CONFIG_DEBUG_TFLITE_LOOP
		/* Wrap and keep going, so a long soak test needs no
		 * intervention. Note the seam: row 1150 is followed
		 * immediately by row 0, which is a step discontinuity in the
		 * trajectory, not a smooth return to centre. The harness's
		 * motion-based anchor logic will see it as one large jump. */
		cursor = 0u;
		passes++;
		LOG_INF("replay: pass %u complete, wrapping to row 0", passes);
#else
		/* Hold the last sample forever. Deliberately NOT returning to
		 * 0.0: freezing on the final recorded value keeps the
		 * trajectory's end state, whereas snapping to centre would
		 * inject a motion event the recording never contained. */
		LOG_INF("replay: reached end of trajectory (%u rows), holding "
			"the last sample", REPLAY_SAMPLE_COUNT);
#endif
	}

	return s;
}

uint32_t replay_cursor(void)
{
	return cursor;
}

uint32_t replay_pass_count(void)
{
	return passes;
}
